                        .HasColumnType("decimal(18,3)");

                    b.Property<long?>("SourceVoucherId")
                        .HasColumnType("bigint");

                    b.Property<string>("UnitOfMeasure")
                        .IsRequired()
                        .HasMaxLength(30)
                        .HasColumnType("nvarchar(30)");

