                        .HasFilter("[DestinationVoucherId] IS NOT NULL");

                    b.HasIndex("SourceMovementId")
                        .IsUnique();

                    b.HasIndex("SourceVoucherId")
                        .IsUnique()
                        .HasFilter("[SourceVoucherId] IS NOT NULL");

                    b.HasIndex("CompanyId", "Reference")
                        .IsUnique();

                    b.HasIndex("CompanyId", "DestinationBranchId", "CreatedUtc");

                    b.HasIndex("CompanyId", "DestinationBranchId", "DestinationMovementId");

                    b.HasIndex("CompanyId", "DestinationBranchId", "DestinationStockItemId");

                    b.HasIndex("CompanyId", "DestinationBranchId", "DestinationVoucherId");

