                    b.HasIndex("CompanyId", "SourceBranchId", "SourceStockItemId");

                    b.HasIndex("CompanyId", "SourceBranchId", "SourceVoucherId");

                    b.ToTable("StockTransfers", t =>
                        {
                            t.HasCheckConstraint("CK_StockTransfer_DifferentBranches", "[SourceBranchId] <> [DestinationBranchId] AND [SourceStockItemId] <> [DestinationStockItemId] AND [SourceMovementId] <> [DestinationMovementId]");

                            t.HasCheckConstraint("CK_StockTransfer_NonnegativeBalances", "[SourceQuantityBefore] >= 0 AND [SourceQuantityAfter] >= 0 AND [DestinationQuantityBefore] >= 0 AND [DestinationQuantityAfter] >= 0 AND [SourceValueBefore] >= 0 AND [SourceValueAfter] >= 0 AND [DestinationValueBefore] >= 0 AND [DestinationValueAfter] >= 0");

                            t.HasCheckConstraint("CK_StockTransfer_PairedVouchers", "([CostAmount] = 0 AND [SourceVoucherId] IS NULL AND [DestinationVoucherId] IS NULL) OR ([CostAmount] > 0 AND [SourceVoucherId] IS NOT NULL AND [DestinationVoucherId] IS NOT NULL AND [SourceVoucherId] <> [DestinationVoucherId])");

                            t.HasCheckConstraint("CK_StockTransfer_PositiveQuantity", "[Quantity] > 0 AND [CostAmount] >= 0");
                        });
                });

